{

    internal InnerConnectionTypeConnectorAuthorizationCodePropertiesFactory AuthorizationCodePropertiesFactory { get; set; }

    internal InnerConnectionTypeClientCredentialsPropertiesFactory ClientCredentialsPropertiesFactory { get; set; }

    internal InnerConnectionTypeJWTBearerPropertiesFactory JWTBearerPropertiesFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.ConnectorOAuth2Properties Create()
    {
        var connectorOAuth2PropertiesResult = CreateConnectorOAuth2Properties();
        factoryAction?.Invoke(connectorOAuth2PropertiesResult);

        return connectorOAuth2PropertiesResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.ConnectorOAuth2Properties CreateConnectorOAuth2Properties()
    {
        var connectorOAuth2PropertiesResult = new Humidifier.Glue.ConnectionTypeTypes.ConnectorOAuth2Properties();

        return connectorOAuth2PropertiesResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.ConnectorOAuth2Properties result)
    {
        base.CreateChildren(result);

        result.AuthorizationCodeProperties ??= AuthorizationCodePropertiesFactory?.Build();
        result.ClientCredentialsProperties ??= ClientCredentialsPropertiesFactory?.Build();
        result.JWTBearerProperties ??= JWTBearerPropertiesFactory?.Build();
    }

} // End Of Class

